import React, { useCallback, useState } from 'react';
import { useDropzone } from 'react-dropzone';
import './App.css';

interface AnalysisResponse {
  insights: string;
  discrepancies: string[];
}

function App() {
  const [files, setFiles] = useState<File[]>([]);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [progress, setProgress] = useState<string[]>([]);
  const [analysis, setAnalysis] = useState<AnalysisResponse | null>(null);
  const [error, setError] = useState<string | null>(null);

  const onDrop = useCallback((acceptedFiles: File[]) => {
    setFiles(prev => [...prev, ...acceptedFiles]);
    setError(null);
  }, []);

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop,
    accept: {
      'image/*': ['.png', '.jpg', '.jpeg', '.gif'],
      'application/pdf': ['.pdf']
    }
  });

  const removeFile = (index: number) => {
    setFiles(prev => prev.filter((_, i) => i !== index));
  };

  const analyzeDocuments = async () => {
    if (files.length < 2) {
      setError('Please upload at least 2 documents');
      return;
    }

    setIsAnalyzing(true);
    setProgress([]);
    setAnalysis(null);
    setError(null);

    const formData = new FormData();
    files.forEach((file, index) => {
      formData.append(`file${index}`, file);
    });

    try {
      const response = await fetch('http://localhost:8000/api/analyze-documents', {
        method: 'POST',
        body: formData,
      });

      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }

      const reader = response.body?.getReader();
      if (!reader) throw new Error('No reader available');

      const decoder = new TextDecoder();

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        const chunk = decoder.decode(value);
        const lines = chunk.split('\n');

        for (const line of lines) {
          if (line.startsWith('data: ')) {
            const data = JSON.parse(line.slice(6));

            if (data.type === 'progress') {
              setProgress(prev => [...prev, data.message]);
            } else if (data.type === 'result') {
              setAnalysis(data.data);
            }
          }
        }
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Error analyzing documents');
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="App">
      <header className="App-header">
        <h1>Trade Document Analyzer</h1>
      </header>
      <main>
        <div className="upload-section">
          <div {...getRootProps()} className={`dropzone ${isDragActive ? 'active' : ''}`}>
            <input {...getInputProps()} />
            {isDragActive ? (
              <p>Drop the files here ...</p>
            ) : (
              <p>Drag 'n' drop some files here, or click to select files</p>
            )}
          </div>

          {files.length > 0 && (
            <div className="file-list">
              <h3>Selected Files:</h3>
              <ul>
                {files.map((file, index) => (
                  <li key={index}>
                    {file.name}
                    <button onClick={() => removeFile(index)}>Remove</button>
                  </li>
                ))}
              </ul>
              <button 
                onClick={analyzeDocuments} 
                disabled={isAnalyzing || files.length < 2}
                className="analyze-button"
              >
                {isAnalyzing ? 'Analyzing...' : 'Analyze Documents'}
              </button>
            </div>
          )}
        </div>

        {error && (
          <div className="error-message">
            {error}
          </div>
        )}

        {progress.length > 0 && (
          <div className="progress-section">
            <h3>Progress:</h3>
            <ul>
              {progress.map((message, index) => (
                <li key={index}>{message}</li>
              ))}
            </ul>
          </div>
        )}

        {analysis && (
          <div className="analysis-section">
            <h3>Analysis Results:</h3>
            <div className="analysis-content">
              <h4>Key Insights:</h4>
              <p>{analysis.insights}</p>

              <h4>Discrepancies:</h4>
              <ul>
                {analysis.discrepancies.map((discrepancy, index) => (
                  <li key={index}>{discrepancy}</li>
                ))}
              </ul>
            </div>
          </div>
        )}
      </main>
    </div>
  );
}

export default App;
